return items.map(item => {
  const subject = item.json.emailSubject?.toLowerCase() || '';
  const body = item.json.emailBody?.toLowerCase() || '';
  const filename = item.json.attachmentName?.toLowerCase() || '';

  let documentType = 'Unknown';
  let storageFolder = 'Medical Records';

  if (subject.includes('referral') || body.includes('referral') || filename.includes('referral')) {
    documentType = 'Referral';
    storageFolder = 'Referrals';
  } else if (subject.includes('lab result') || subject.includes('test result') ||
             body.includes('lab result') || filename.includes('lab')) {
    documentType = 'Lab Result';
    storageFolder = 'Lab Results';
  } else if (subject.includes('insurance') || filename.includes('insurance') || 
             body.includes('insurance')) {
    documentType = 'Insurance Document';
    storageFolder = 'Insurance Documents';
  } else if (subject.includes('prescription') || filename.includes('prescription') || 
             body.includes('prescription')) {
    documentType = 'Prescription';
    storageFolder = 'Prescriptions';
  }

  return {
    json: {
      ...item.json,
      documentType,
      storageFolder
    },
    binary: item.binary // ✅ keep the Gmail file for upload
  };
});

return items.map(item => {
  const binary = item.binary || {};
  const attachmentKey = Object.keys(binary)[0] || 'attachment_0';
  const attachment = binary[attachmentKey] || {};

  return {
    json: {
      emailSubject: item.json.subject || '',
      senderEmail: item.json.from?.value?.[0]?.address || '',
      senderName: item.json.from?.value?.[0]?.name || '',
      receivedDate: new Date().toISOString().replace('T', ' ').substring(0, 19),
      emailBody: item.json.text || '',
      attachmentName: attachment.fileName || '',
      attachmentData: JSON.stringify(attachment) || '',
      attachmentMimeType: attachment.mimeType || '',
      documentId: `MED-${new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 15)}`
    },
    binary // ✅ preserve the original attachment binary for upload later
  };
});

