// Node names
const lookupNode = "Find Patient in Database";
const parseNode = "Parse AI Response";

// Get data from both
const lookupData = $items(lookupNode)[0];
const parsedData = $items(parseNode)[0];

// Check if lookup node found a match
const patientExists = lookupData && lookupData.json && Object.keys(lookupData.json).length > 0;

// If found in database, return that data
if (patientExists) {
  return [
    {
      json: {
        source: "database",
        exists: true,
        ...lookupData.json
      }
    }
  ];
} else {
  // Otherwise, use data from the AI parser
  return [
    {
      json: {
        source: "ai",
        exists: false,
        ...parsedData.json
      }
    }
  ];
}

const timeframe = $('Parse AI Response').first().json.followUpTimeframe || 'Within 2 weeks';
const today = new Date();
let followUpDate = new Date(today);

// Parse timeframe and calculate date
if (timeframe.toLowerCase().includes('1 week') || timeframe.toLowerCase().includes('one week')) {
  followUpDate.setDate(today.getDate() + 7);
} else if (timeframe.toLowerCase().includes('2 week') || timeframe.toLowerCase().includes('two week')) {
  followUpDate.setDate(today.getDate() + 14);
} else if (timeframe.toLowerCase().includes('1 month') || timeframe.toLowerCase().includes('one month')) {
  followUpDate.setMonth(today.getMonth() + 1);
} else if (timeframe.toLowerCase().includes('3 month')) {
  followUpDate.setMonth(today.getMonth() + 3);
} else if (timeframe.toLowerCase().includes('6 month')) {
  followUpDate.setMonth(today.getMonth() + 6);
} else {
  // Default to 2 weeks
  followUpDate.setDate(today.getDate() + 14);
}

// Set to 9 AM
followUpDate.setHours(9, 0, 0, 0);

return {
  json: {
    followUpDate: followUpDate.toISOString().split('T')[0],
    followUpDateTime: followUpDate.toISOString(),
    followUpTimeDisplay: followUpDate.toLocaleString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }
};

